// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Changes: module, agent tool and text diffs"
// Changes: Tests of the changes module – what adopting a draft would do to its project: line diffs of the text
//          parts, precedence terminal and cell changes, LL table cell and conflict changes caused by grammar rule
//          edits, Empty/First/Follow/Predict changes and the per-part "changed" / "changed on both sides" flags.

import { describe, expect, it } from 'vitest'
import { draftChanges } from './changes'
import { PARTS, type Parts } from './parts'

// E → id | id + E has an LL(1) conflict in cell [E, id]; the fixed grammar factors it out.
const CONFLICTING = 'E -> id\nE -> id + E'
const FIXED = 'E -> id R\nR -> + E\nR -> eps'

function project(): Parts {
  return {
    definition: { nonterminals: 'E', terminals: 'id\n+', start: 'E' },
    grammarRules: CONFLICTING,
    precTable: { terminals: ['+', 'id'], cells: { 'id\u0001+': '>', '+\u0001id': '<' } },
    reductionRules: 'E -> E + E\nE -> id',
  }
}

const draftOf = (base: Parts, patch: Partial<Parts>): Parts => ({ ...base, ...patch })

describe('line diffs of the text parts', () => {
  it('grammar rules: unchanged, removed and added lines with their old and new line numbers', () => {
    const p = project()
    const changes = draftChanges({ project: p, draft: draftOf(p, { grammarRules: 'E -> id\nE -> ( E )\nE -> id + E\nE -> num' }) })
    expect(changes.grammarRules.lines).toEqual([
      { kind: 'same', text: 'E -> id', oldLine: 1, newLine: 1 },
      { kind: 'added', text: 'E -> ( E )', oldLine: null, newLine: 2 },
      { kind: 'same', text: 'E -> id + E', oldLine: 2, newLine: 3 },
      { kind: 'added', text: 'E -> num', oldLine: null, newLine: 4 },
    ])
  })

  it('reduction rules: a changed line is the old line removed and the new one added in its place', () => {
    const p = project()
    const changes = draftChanges({ project: p, draft: draftOf(p, { reductionRules: 'E -> E * E\nE -> id' }) })
    expect(changes.reductionRules.lines).toEqual([
      { kind: 'removed', text: 'E -> E + E', oldLine: 1, newLine: null },
      { kind: 'added', text: 'E -> E * E', oldLine: null, newLine: 1 },
      { kind: 'same', text: 'E -> id', oldLine: 2, newLine: 2 },
    ])
  })

  it('definition: N, T and S are diffed line by line on their own', () => {
    const p = project()
    const changes = draftChanges({
      project: p,
      draft: draftOf(p, { definition: { nonterminals: 'E\nR   zvyšok výrazu', terminals: 'id\n+', start: '' } }),
    })
    expect(changes.definition.nonterminals).toEqual([
      { kind: 'same', text: 'E', oldLine: 1, newLine: 1 },
      { kind: 'added', text: 'R   zvyšok výrazu', oldLine: null, newLine: 2 },
    ])
    expect(changes.definition.terminals.every((l) => l.kind === 'same')).toBe(true)
    expect(changes.definition.start).toEqual([{ kind: 'removed', text: 'E', oldLine: 1, newLine: null }])
  })

  it('an emptied text is all removed lines; an unchanged one is all unchanged lines', () => {
    const p = project()
    const changes = draftChanges({ project: p, draft: draftOf(p, { reductionRules: '' }) })
    expect(changes.reductionRules.lines.map((l) => l.kind)).toEqual(['removed', 'removed'])
    expect(changes.grammarRules.lines.map((l) => l.kind)).toEqual(['same', 'same'])
  })
})

describe('precedence table changes', () => {
  it('an added terminal and changed cells (old → new), including set ↔ empty, in grid order', () => {
    const p = project()
    const changes = draftChanges({
      project: p,
      draft: draftOf(p, { precTable: { terminals: ['+', 'id', '*'], cells: { 'id\u0001+': '<', '*\u0001id': '<' } } }),
    })
    expect(changes.precTable.addedTerminals).toEqual(['*'])
    expect(changes.precTable.removedTerminals).toEqual([])
    expect(changes.precTable.cells).toEqual([
      { stack: '+', input: 'id', old: '<', new: '' },
      { stack: 'id', input: '+', old: '>', new: '<' },
      { stack: '*', input: 'id', old: '', new: '<' },
    ])
  })

  it('a removed terminal takes its relations with it', () => {
    const p = project()
    const changes = draftChanges({ project: p, draft: draftOf(p, { precTable: { terminals: ['id'], cells: { 'id\u0001+': '>' } } }) })
    expect(changes.precTable.addedTerminals).toEqual([])
    expect(changes.precTable.removedTerminals).toEqual(['+'])
    expect(changes.precTable.cells).toEqual([
      { stack: 'id', input: '+', old: '>', new: '' },
      { stack: '+', input: 'id', old: '<', new: '' },
    ])
  })

  it('relations with $ count like any other cell', () => {
    const p = project()
    const changes = draftChanges({
      project: p,
      draft: draftOf(p, { precTable: { terminals: ['+', 'id'], cells: { ...p.precTable.cells, '$\u0001id': '<' } } }),
    })
    expect(changes.precTable.cells).toEqual([{ stack: '$', input: 'id', old: '', new: '<' }])
  })
})

// The fix of the conflict: a new nonterminal R takes the rest of the expression.
const fixedDefinition = { nonterminals: 'E\nR', terminals: 'id\n+', start: 'E' }

describe('LL table changes caused by grammar rule edits', () => {
  it('cells whose rules differ, and the conflict the fix resolves', () => {
    const p = project()
    const changes = draftChanges({ project: p, draft: draftOf(p, { grammarRules: FIXED, definition: fixedDefinition }) })
    expect(changes.llTable.cells).toEqual([
      {
        nonterminal: 'E',
        terminal: 'id',
        old: [
          { rule: 1, text: 'E → id' },
          { rule: 2, text: 'E → id + E' },
        ],
        new: [{ rule: 1, text: 'E → id R' }],
      },
      { nonterminal: 'R', terminal: '+', old: [], new: [{ rule: 2, text: 'R → + E' }] },
      { nonterminal: 'R', terminal: '$', old: [], new: [{ rule: 3, text: 'R → ε' }] },
    ])
    expect(changes.llTable.resolvedConflicts).toEqual([
      {
        nonterminal: 'E',
        terminal: 'id',
        rules: [
          { rule: 1, text: 'E → id' },
          { rule: 2, text: 'E → id + E' },
        ],
      },
    ])
    expect(changes.llTable.newConflicts).toEqual([])
  })

  it('a grammar rule edit that introduces a conflict calls it out as new', () => {
    const fixed = { ...project(), grammarRules: FIXED, definition: fixedDefinition }
    const changes = draftChanges({ project: fixed, draft: draftOf(fixed, { grammarRules: FIXED + '\nE -> id' }) })
    expect(changes.llTable.newConflicts).toEqual([
      {
        nonterminal: 'E',
        terminal: 'id',
        rules: [
          { rule: 1, text: 'E → id R' },
          { rule: 4, text: 'E → id' },
        ],
      },
    ])
    expect(changes.llTable.resolvedConflicts).toEqual([])
  })

  it('the same rule under a new number is a changed cell (the tab shows the number)', () => {
    const p = project()
    const changes = draftChanges({ project: p, draft: draftOf(p, { grammarRules: 'E -> id + E\nE -> id' }) })
    expect(changes.llTable.cells).toEqual([
      {
        nonterminal: 'E',
        terminal: 'id',
        old: [
          { rule: 1, text: 'E → id' },
          { rule: 2, text: 'E → id + E' },
        ],
        new: [
          { rule: 1, text: 'E → id + E' },
          { rule: 2, text: 'E → id' },
        ],
      },
    ])
    // Still a conflict on both sides: neither new nor resolved.
    expect(changes.llTable.newConflicts).toEqual([])
    expect(changes.llTable.resolvedConflicts).toEqual([])
  })

  it('no grammar rules on one side: every cell of the other side differs', () => {
    const p = project()
    const changes = draftChanges({ project: p, draft: draftOf(p, { grammarRules: '' }) })
    expect(changes.llTable.cells).toEqual([
      {
        nonterminal: 'E',
        terminal: 'id',
        old: [
          { rule: 1, text: 'E → id' },
          { rule: 2, text: 'E → id + E' },
        ],
        new: [],
      },
    ])
    expect(changes.llTable.resolvedConflicts).toHaveLength(1)
  })
})

describe('set changes', () => {
  it('changed Empty, First and Follow entries per nonterminal and changed Predict entries per rule', () => {
    const p = project()
    const changes = draftChanges({ project: p, draft: draftOf(p, { grammarRules: FIXED, definition: fixedDefinition }) })
    // E keeps Empty, First and Follow; R is new.
    expect(changes.sets.nonterminals).toEqual([
      { nonterminal: 'R', old: null, new: { empty: true, first: ['+'], follow: ['$'] }, changed: ['empty', 'first', 'follow'] },
    ])
    expect(changes.sets.predict).toEqual([
      { rule: 1, old: { text: 'E → id', predict: ['id'] }, new: { text: 'E → id R', predict: ['id'] }, changed: ['text'] },
      { rule: 2, old: { text: 'E → id + E', predict: ['id'] }, new: { text: 'R → + E', predict: ['+'] }, changed: ['text', 'predict'] },
      { rule: 3, old: null, new: { text: 'R → ε', predict: ['$'] }, changed: ['text', 'predict'] },
    ])
  })

  it('a nonterminal the draft drops is listed with its old sets', () => {
    const fixed = { ...project(), grammarRules: FIXED, definition: fixedDefinition }
    const changes = draftChanges({ project: fixed, draft: project() })
    expect(changes.sets.nonterminals).toEqual([
      { nonterminal: 'R', old: { empty: true, first: ['+'], follow: ['$'] }, new: null, changed: ['empty', 'first', 'follow'] },
    ])
    expect(changes.sets.predict.at(-1)).toEqual({ rule: 3, old: { text: 'R → ε', predict: ['$'] }, new: null, changed: ['text', 'predict'] })
  })

  it('Follow changes when a rule uses a nonterminal in a new context', () => {
    const fixed = { ...project(), grammarRules: FIXED, definition: fixedDefinition }
    const changes = draftChanges({
      project: fixed,
      draft: { ...fixed, grammarRules: FIXED + '\nR -> E +', definition: fixedDefinition },
    })
    expect(changes.sets.nonterminals.find((n) => n.nonterminal === 'E')).toEqual({
      nonterminal: 'E',
      old: { empty: false, first: ['id'], follow: ['$'] },
      new: { empty: false, first: ['id'], follow: ['+', '$'] },
      changed: ['follow'],
    })
  })
})

describe('per-part flags', () => {
  it('a part is changed when the draft differs from the current project', () => {
    const p = project()
    const changes = draftChanges({ project: p, draft: draftOf(p, { reductionRules: 'E -> id' }) })
    expect(PARTS.map((part) => [part, changes[part].changed])).toEqual([
      ['definition', false],
      ['grammarRules', false],
      ['precTable', false],
      ['reductionRules', true],
    ])
  })

  it('without the base, "changed on both sides" is unknown', () => {
    const p = project()
    const changes = draftChanges({ project: p, draft: draftOf(p, { grammarRules: FIXED }) })
    expect(PARTS.map((part) => changes[part].changedOnBothSides)).toEqual([null, null, null, null])
  })

  it('with the base: changed on both sides only when the project and the draft both moved away from the base', () => {
    const base = project()
    // The human edited the grammar rules and the reduction rules in the project since the draft was made…
    const current = { ...base, grammarRules: base.grammarRules + '\nE -> num', reductionRules: 'E -> id' }
    // …and the draft changed the grammar rules and the precedence table.
    const draft = draftOf(base, { grammarRules: FIXED, precTable: { terminals: ['id'], cells: {} } })
    const changes = draftChanges({ project: current, draft, base })
    expect(PARTS.map((part) => [part, changes[part].changed, changes[part].changedOnBothSides])).toEqual([
      ['definition', false, false],
      ['grammarRules', true, true],
      ['precTable', true, false],
      // Changed only in the project: adopting it would bring back the base text, but it is not "both sides".
      ['reductionRules', true, false],
    ])
  })

  it('the precedence table compares as the grid: the order of stored cells does not matter, the terminal order does', () => {
    const p = project()
    const reordered = { terminals: ['+', 'id'], cells: { '+\u0001id': '<' as const, 'id\u0001+': '>' as const } }
    expect(draftChanges({ project: p, draft: draftOf(p, { precTable: reordered }) }).precTable.changed).toBe(false)
    const swapped = { ...reordered, terminals: ['id', '+'] }
    const changes = draftChanges({ project: p, draft: draftOf(p, { precTable: swapped }) })
    expect(changes.precTable.changed).toBe(true)
    expect(changes.precTable.cells).toEqual([])
  })
})
